import { useMutation, UseMutationOptions } from '@tanstack/react-query';
import { AccountValidRequestDTO, AccountValidResponseDTO } from '~/entities/wallet/api/dtos/account-valid';
import { walletApi } from '~/entities/wallet/api/wallet-api';
import { CBDCAxiosError } from '~/shared/@types/error';

export const useAccountValidMutation = (
  options?: UseMutationOptions<AccountValidResponseDTO, CBDCAxiosError, AccountValidRequestDTO>,
) => {
  const mutation = useMutation<AccountValidResponseDTO, CBDCAxiosError, AccountValidRequestDTO>({
    ...options,
    mutationFn: walletApi.accountValid,
  });

  return {
    ...mutation,
  };
};
